/**
 * RGC Export Integration Test
 *
 * This test verifies that:
 * 1. RGC settings are passed to export shader builder
 * 2. Export shader contains RGC functions when enabled
 * 3. Exported EXR has correct pixel values
 *
 * IMPORTANT: These tests read debug files generated by actual VS Code exports.
 * The debug files are written to: images/test_patterns/test_results/
 *
 * To regenerate debug files:
 * 1. Open VS Code with the DCTL Workbench extension
 * 2. Open an EXR file (e.g., images/test_patterns/color_checker_ap0.exr)
 * 3. Load a DCTL file (e.g., images/dctl_viewer_tests/test_gain.dctl)
 * 4. Enable RGC checkbox and set gain parameter
 * 5. Use "Export as EXR" command
 *
 * Can run with: npm test (mocha) or npm run test:vscode (VS Code test runner)
 */

import * as assert from 'assert';
import * as path from 'path';
import * as fs from 'fs';
import { getTestOutputDir } from '@dctl-workbench/core/out/test-paths.js';

// Note: vscode import only available when running inside VS Code
// import * as vscode from 'vscode';

describe('RGC Export Integration Tests', () => {
    const testResultsDir = getTestOutputDir();
    const testImagesDir = getTestOutputDir();

    /**
     * Verify the export shader debug files
     *
     * NOTE: This test requires a fresh debug file generated by VS Code export.
     * If the test is skipped, run an export in VS Code with RGC enabled to generate
     * the debug file at: images/test_patterns/test_results/export_shader_rgc_debug.wgsl
     */
    it('RGC export shader should not have duplicate entry points', async function () {
        this.timeout(60000);

        const rgcDebugPath = path.join(testResultsDir, 'export_shader_rgc_debug.wgsl');

        if (!fs.existsSync(rgcDebugPath)) {
            console.log('\n=== RGC Debug File Not Found ===');
            console.log('Path:', rgcDebugPath);
            console.log('To generate this file:');
            console.log('1. Open VS Code with DCTL Workbench extension');
            console.log('2. Open an EXR file and load a DCTL');
            console.log('3. Enable RGC checkbox');
            console.log('4. Use "Export as EXR" command');
            this.skip();
            return;
        }

        const shaderCode = fs.readFileSync(rgcDebugPath, 'utf-8');

        // Count @fragment fn main declarations
        const fragmentMainMatches = shaderCode.match(/@fragment\s*\n?\s*fn\s+main/g);
        const fragmentMainCount = fragmentMainMatches ? fragmentMainMatches.length : 0;

        console.log(`\n=== RGC Export Shader Entry Point Check ===`);
        console.log(`Found ${fragmentMainCount} @fragment fn main declarations`);

        if (fragmentMainCount > 1) {
            console.log('ERROR: Duplicate entry points detected!');
            console.log('Locations:');
            let searchIndex = 0;
            while (true) {
                const idx = shaderCode.indexOf('@fragment', searchIndex);
                if (idx === -1) break;
                const lineNum = shaderCode.substring(0, idx).split('\n').length;
                console.log(`  Line ${lineNum}`);
                searchIndex = idx + 1;
            }
        }

        assert.strictEqual(
            fragmentMainCount,
            1,
            `Expected exactly 1 @fragment fn main, found ${fragmentMainCount}`
        );
    });

    it('RGC export shader should have RGC functions', async function () {
        this.timeout(60000);

        const rgcDebugPath = path.join(testResultsDir, 'export_shader_rgc_debug.wgsl');

        if (!fs.existsSync(rgcDebugPath)) {
            this.skip();
            return;
        }

        const shaderCode = fs.readFileSync(rgcDebugPath, 'utf-8');

        console.log('\n=== RGC Export Shader Function Check ===');

        // Check for RGC-specific functions
        const checks = {
            hasApplyRGC: /fn\s+applyACES2RGC/.test(shaderCode),
            hasRgcHelpers: /fn\s+rgc_ocio_/.test(shaderCode),
            hasRgcTextures: /@group\(0\)\s*@binding\([2-9]\)/.test(shaderCode),
            hasHuesArray: /rgc_ocio_gamut_cusp_table_0_hues_array/.test(shaderCode),
            hasTransform: /fn\s+transform\s*\(/.test(shaderCode),
            hasFragmentEntry: /@fragment\s*\n?\s*fn\s+main/.test(shaderCode),
        };

        for (const [name, passed] of Object.entries(checks)) {
            console.log(`${name}: ${passed ? '✓' : '✗'}`);
        }

        // Key assertions
        assert.ok(checks.hasApplyRGC, 'Should have applyACES2RGC function');
        assert.ok(checks.hasTransform, 'Should have transform function');
        assert.ok(checks.hasFragmentEntry, 'Should have fragment entry point');
    });

    it('RGC shader should apply RGC in texture sampling', async function () {
        this.timeout(60000);

        const rgcDebugPath = path.join(testResultsDir, 'export_shader_rgc_debug.wgsl');

        if (!fs.existsSync(rgcDebugPath)) {
            this.skip();
            return;
        }

        const shaderCode = fs.readFileSync(rgcDebugPath, 'utf-8');

        console.log('\n=== RGC Application Check ===');

        // Check if dctl_sampleTexture calls applyACES2RGC
        const sampleTextureMatch = shaderCode.match(
            /fn dctl_sampleTexture[\s\S]*?(?=\nfn\s|\n\/\/\s*Fragment|\Z)/
        );

        if (sampleTextureMatch) {
            const sampleFn = sampleTextureMatch[0];
            const callsRGC = /applyACES2RGC/.test(sampleFn);
            console.log(`dctl_sampleTexture calls applyACES2RGC: ${callsRGC ? '✓' : '✗'}`);

            // If RGC is enabled, it should call applyACES2RGC
            if (!callsRGC) {
                console.log('WARNING: RGC shader does not apply RGC in dctl_sampleTexture');
                console.log('dctl_sampleTexture function:');
                console.log(sampleFn.substring(0, 500));
            }
        }
    });

    it('Non-RGC export shader should not have RGC functions', async function () {
        this.timeout(60000);

        const nonRgcDebugPath = path.join(testResultsDir, 'export_shader_debug.wgsl');

        if (!fs.existsSync(nonRgcDebugPath)) {
            this.skip();
            return;
        }

        const shaderCode = fs.readFileSync(nonRgcDebugPath, 'utf-8');

        console.log('\n=== Non-RGC Export Shader Check ===');

        const hasRgcCode = /applyACES2RGC|rgc_ocio_/.test(shaderCode);
        console.log(`Contains RGC code: ${hasRgcCode ? '✗ (unexpected)' : '✓ (expected)'}`);

        // Non-RGC shader should NOT have RGC functions
        assert.ok(!hasRgcCode, 'Non-RGC shader should not contain RGC functions');

        // But should have transform
        const hasTransform = /fn\s+transform/.test(shaderCode);
        assert.ok(hasTransform, 'Non-RGC shader should have transform function');
    });

    it('Parameter injection should work in both RGC and non-RGC paths', async function () {
        this.timeout(60000);

        const paths = [
            { name: 'Non-RGC', path: path.join(testResultsDir, 'export_shader_debug.wgsl') },
            { name: 'RGC', path: path.join(testResultsDir, 'export_shader_rgc_debug.wgsl') },
        ];

        console.log('\n=== Parameter Injection Check ===');

        for (const { name, path: filePath } of paths) {
            if (!fs.existsSync(filePath)) {
                console.log(`${name}: File not found (skipped)`);
                continue;
            }

            const shaderCode = fs.readFileSync(filePath, 'utf-8');

            // Find gain parameter
            const gainMatch = shaderCode.match(/var<private>\s+gain:\s*f32\s*=\s*([^;]+);/);
            if (gainMatch) {
                const hasValue = gainMatch[1].trim() !== '';
                console.log(`${name}: gain = ${gainMatch[1].trim()} ${hasValue ? '✓' : '✗'}`);

                if (!hasValue) {
                    assert.fail(`${name} path: gain parameter not initialized`);
                }
            } else {
                // Check if gain is declared without value
                const gainDecl = shaderCode.match(/var<private>\s+gain:\s*f32\s*;/);
                if (gainDecl) {
                    console.log(`${name}: gain declared but NOT initialized ✗`);
                    assert.fail(`${name} path: gain parameter declared but not initialized`);
                } else {
                    console.log(`${name}: No gain parameter (may be different DCTL)`);
                }
            }
        }
    });

    /**
     * Compare RGC vs non-RGC shader sizes
     */
    it('RGC shader should be larger than non-RGC shader', async function () {
        this.timeout(60000);

        const nonRgcPath = path.join(testResultsDir, 'export_shader_debug.wgsl');
        const rgcPath = path.join(testResultsDir, 'export_shader_rgc_debug.wgsl');

        if (!fs.existsSync(nonRgcPath) || !fs.existsSync(rgcPath)) {
            console.log('Both debug files required for comparison');
            this.skip();
            return;
        }

        const nonRgcSize = fs.statSync(nonRgcPath).size;
        const rgcSize = fs.statSync(rgcPath).size;

        console.log('\n=== Shader Size Comparison ===');
        console.log(`Non-RGC: ${nonRgcSize} bytes`);
        console.log(`RGC: ${rgcSize} bytes`);
        console.log(`Difference: ${rgcSize - nonRgcSize} bytes`);

        // RGC shader should be significantly larger (RGC adds ~15KB+ of code)
        const sizeDiff = rgcSize - nonRgcSize;
        assert.ok(
            sizeDiff > 5000,
            `RGC shader should be at least 5KB larger, got ${sizeDiff} bytes difference`
        );
    });

    /**
     * Verify exported EXR pixel values
     */
    it('Exported EXR should have correct pixel values with gain applied', async function () {
        this.timeout(120000);

        // This test requires the extension to be loaded and working
        // For now, we check if the exported file exists and has reasonable size

        const exportedPaths = [
            path.join(testImagesDir, 'color_checker_ap0_dctl_export.exr'),
            path.join(testResultsDir, 'exported_with_gain.exr'),
        ];

        console.log('\n=== Exported EXR Check ===');

        for (const exportedPath of exportedPaths) {
            if (fs.existsSync(exportedPath)) {
                const stats = fs.statSync(exportedPath);
                console.log(`Found: ${path.basename(exportedPath)}`);
                console.log(`  Size: ${stats.size} bytes`);
                console.log(`  Modified: ${stats.mtime.toISOString()}`);

                // EXR file should be at least 1KB
                assert.ok(stats.size > 1024, 'Exported EXR should be at least 1KB');
            } else {
                console.log(`Not found: ${path.basename(exportedPath)}`);
            }
        }
    });
});

